def transform(grid):
    """Compare corresponding cells in panels split by a solid center line.

    Equal cells are marked with 3. Unequal cells receive the sole color
    shared by the panels' palettes.
    """
    h, w = len(grid), len(grid[0])
    panels = None
    for c in range(1, w - 1):
        if c == w - c - 1 and all(row[c] == grid[0][c] for row in grid):
            panels = ([row[:c] for row in grid], [row[c + 1:] for row in grid])
            break
    if panels is None:
        for r in range(1, h - 1):
            if r == h - r - 1 and len(set(grid[r])) == 1:
                panels = (grid[:r], grid[r + 1:])
                break
    if panels is None:
        raise ValueError("expected equally sized panels separated by a centered line")

    a, b = panels
    colors_a = set(v for row in a for v in row)
    colors_b = set(v for row in b for v in row)
    shared = colors_a & colors_b
    if len(shared) != 1:
        raise ValueError(f"expected exactly one shared panel color, got {shared}")
    common = next(iter(shared))
    return [[3 if a[r][c] == b[r][c] else common
